// <autogenerated />
using Microsoft.AspNetCore.Components;
using Shared.DTO.Customer;
using System.Net.Http.Json;

namespace HandymanWorkshop.Client.Pages.Customer
{
    public partial class Delete
    {
        [Parameter]
        public string id { get; set; }

        CustomerDto customer { get; set; } = new CustomerDto();

        [Inject]
        protected NavigationManager? NavMan { get; set; }

        protected bool show { get; set; } = false;

        protected async override Task OnInitializedAsync()
        {
            try
            {
                customer = await Http.GetFromJsonAsync<CustomerDto>("api/Customers/" + id);
                show = true;
            }
            catch
            {

            }
        }

        protected async Task DeleteCustomer()
        {
            var response = await Http.DeleteAsync("api/Customers/" + id);
            if (response.IsSuccessStatusCode)
            {
                NavMan.NavigateTo("/Customer");
            }
            else
            {
                Console.WriteLine($"Error >> {response.ReasonPhrase}");
            }
        }
    }
}
